import { atom, read, update } from 'claude-code'
import type { EngineInterface, Register, RenderElement } from 'claude-code'

import type { Activity, ActivityKind, Avatar, Engine, Reaction, Stage } from '../types'
import { AVATARS, avatarCells, heightOf, homeOf, isAvatar, rowsOf, stepWalk, strideOf } from './avatar'
import { cupOf } from './cup'
import { nudgeOf } from './hub'
import type { Nudge } from './hub'
import { canonicalModel, effortMeter, modelLabel, settingsEffort } from './engine'
import { EVOLVE_MS, evolutionToast, stageFor } from './evolve'
import { LISTEN_FOR_MS, SLEEP_AFTER_MS, afterTurn, lookAt, promptReaction, toolActivity } from './mood'
import { flipbook } from './flipbook'
import { NAMES, formName, withArticle } from './names'
import { FRAME_MS, MIN_WIDTH, SVG_SCALE } from './sprite'
import type { Walk } from './walk'

const AVATAR = 'sprout'
/** Columns the model and effort label takes at the band's right end. */
const LABEL_W = 16
const ENGINE_EVERY = 20
/** The widest strip Sprout walks where it is drawn as an SVG. */
const SVG_MAX_W = 60

const activity = atom({ plugin: 'sprout', key: 'activity' } as const, { kind: 'idle', since: 0 })
const reaction = atom({ plugin: 'sprout', key: 'reaction' } as const, null)
const engine = atom({ plugin: 'sprout', key: 'engine' } as const, { model: '', effort: '' })
const stageAtom = atom({ plugin: 'sprout', key: 'stage' } as const, 0)
const avatarAtom = atom({ plugin: 'sprout', key: 'avatar' } as const, 'toad')
// The caffeinate mod's hold, read for the coffee cup above the label; never written here.
const caffeine = { plugin: 'caffeinate', key: 'caffeine' } as const
// The session hub's counts, read for the nudge when another session wants you; never written here.
const hubCounts = { plugin: 'session-hub', key: 'counts' } as const

// The frame clock runs eight times a second, so it reads these mirrors, not
// the host's state. This module is the values' only writer, so the mirrors
// cannot drift, and a reload reads them back from the state.
let act: Activity = { kind: 'idle', since: 0 }
let react: Reaction | null = null
let tick = 0
let bandId: string | undefined
let width = MIN_WIDTH
// Placed at home, the strip's right end, on the first draw (x -1 until then).
let walk: Walk = { x: -1, target: -1, facing: -1 }
let isAnimating = true
let isDrawing = false
let lastCells = ''
let lastEditAt = 0
let isWorking = false
// Claude ended its turn with a question: Sprout waits on the answer until the
// person sends one, through any typing they do and undo meanwhile.
let isAsked = false
let streaming: 'thinking' | 'talking' | undefined
// What the last model request of a turn ran on: the model as resolved, and
// its effort, which the settings may not show (an /effort for this session).
let stepModel: string | undefined
let stepEffort: { model: string; effort: string } | undefined
let shownEngine: Engine = { model: '', effort: '' }
let nudge: Nudge = 'none'
// The line Sprout is drawn as (/avatar, kept between sessions) and how far
// along it the context fill has him, mirrored for the frame clock as the others are.
let avatar: Avatar = 'toad'
let stage: Stage = 0

function loopOf(e: object): string | undefined {
  const { agentId } = e as { agentId?: unknown }

  return typeof agentId === 'string' ? agentId : undefined
}

async function setActivity($: EngineInterface, kind: ActivityKind): Promise<void> {
  if (act.kind === kind) return
  act = { kind, since: await $.clock.now() }
  const next = act
  await update($, activity, () => next)
}

async function setReaction($: EngineInterface, next: Reaction | null): Promise<void> {
  react = next
  await update($, reaction, () => next)
}

// The live model, as /model shows it (a bare alias falls back to the model the
// last request resolved), and its effort: the last request's, else the settings'.
async function refreshEngine($: EngineInterface): Promise<void> {
  const live = await $.session.model()
  const model = /\d/.test(live) ? live : (stepModel ?? live)
  const effort =
    stepEffort && stepEffort.model === canonicalModel(model)
      ? stepEffort.effort
      : settingsEffort((await $.settings.read()) as Record<string, unknown>, model)
  if (shownEngine.model === model && shownEngine.effort === effort) return
  shownEngine = { model, effort }
  const next = shownEngine
  await update($, engine, () => next)
}

// The context fill picks Sprout's stage. A change while the session runs plays
// the evolution and says why; one found at the start (a resumed session) is
// taken as it is.
async function setContext($: EngineInterface, percent: number | undefined, isQuiet = false): Promise<void> {
  const next = stageFor(percent)
  if (next === stage) return
  const from = { avatar, stage }
  stage = next
  await update($, stageAtom, () => next)
  if (isQuiet) return
  await setReaction($, { kind: 'evolving', until: (await $.clock.now()) + EVOLVE_MS, from })
  $.ui.toast(evolutionToast(avatar, from.stage, next, percent))
}

// A new avatar flashes in as an evolution does, from the old one, at the same
// stage; it is kept for every session after.
async function setAvatar($: EngineInterface, next: Avatar): Promise<void> {
  if (next === avatar) return
  const from = { avatar, stage }
  avatar = next
  await update($, avatarAtom, () => next)
  await $.store.set('avatar', next)
  await setReaction($, { kind: 'evolving', until: (await $.clock.now()) + EVOLVE_MS, from })
}

/** The avatar a word names: its id, its line, or one of its forms (`inferno` is the Lizard line). */
function avatarNamed(word: string): Avatar | undefined {
  const said = word.trim().toLowerCase()
  if (said === '') return undefined
  return AVATARS.find(
    id => id === said || NAMES[id].line.toLowerCase() === said || NAMES[id].forms.some(name => name.toLowerCase() === said),
  )
}

// One frame: lapse what has run its time, take a step, then repaint the strip
// when the picture changed. A refused blit (the band collapsed, a survey up,
// a surface with no Raster) stops the clock's painting until the next draw.
async function frame($: EngineInterface): Promise<void> {
  const now = await $.clock.now()
  if (react && now >= react.until) await setReaction($, null)
  if (act.kind === 'listening' && now - lastEditAt > LISTEN_FOR_MS) await setActivity($, isAsked ? 'awaiting' : 'idle')
  if (act.kind === 'idle' && act.since > 0 && now - act.since > SLEEP_AFTER_MS) await setActivity($, 'sleeping')
  if (!isAnimating || bandId === undefined) return

  tick += 1
  if (tick % ENGINE_EVERY === 0) {
    await refreshEngine($)
    nudge = nudgeOf((await $.state.get(hubCounts).catch(() => undefined))?.value)
  }
  const look = lookAt(act, react, now)
  walk = stepWalk(avatar, walk, look, tick, homeOf(width, avatar, stage), Math.random(), Math.random())
  const cells = avatarCells(avatar, stage, width, walk.x, look, tick, strideOf(walk), nudge, react?.from)
  if (cells === lastCells) return
  lastCells = cells
  const painted = await $.ui
    .blit({ requestId: bandId, key: AVATAR, cells, columns: width, rows: rowsOf(avatar) })
    .catch(() => ({ deny: 'failed' }))
  if (painted.deny) isAnimating = false
}

export const register: Register = on => {
  on('session.start', async ($, e, next) => {
    const started = await next(e)
    act = await read($, activity)
    react = await read($, reaction)
    isAsked = act.kind === 'awaiting'
    if (act.since === 0) {
      act = { kind: 'idle', since: await $.clock.now() }
      const fresh = act
      await update($, activity, () => fresh)
    }
    shownEngine = await read($, engine)
    await refreshEngine($)
    const kept = await $.store.get('avatar')
    avatar = isAvatar(kept) ? kept : 'toad'
    const chosen = avatar
    await update($, avatarAtom, () => chosen)
    stage = await read($, stageAtom)
    await setContext($, (await $.session.usage()).context.percent, true)
    await $.command.register({
      name: 'avatar',
      description: 'Choose who Sprout is: the Toad, Lizard or Fox line',
      argumentHint: '[toad|lizard|fox]',
    })
    $.clock.every(FRAME_MS, () => {
      if (isDrawing) return
      isDrawing = true
      void frame($).finally(() => {
        isDrawing = false
      })
    })

    return started
  })

  // `/avatar lizard` switches at once; `/avatar` alone asks which, in the
  // engine's own picker. Any form's name picks its line.
  on('command.run', { command: 'avatar' }, async ($, e) => {
    const options = AVATARS.map(id => `${NAMES[id].line}${id === avatar ? ' (now)' : ''}`)
    const asked =
      avatarNamed(e.args) ??
      (e.args.trim() === ''
        ? await $.ui
            .ask('Which line should Sprout be?', { options, header: 'Avatar' })
            .then(answer => avatarNamed(answer.replace(/ \(now\)$/, '')))
            .catch(() => undefined)
        : undefined)
    if (!asked) return { text: `Sprout can be ${AVATARS.map(id => `/avatar ${id}`).join(', ')}.` }
    if (asked === avatar) return { text: `Sprout is already the ${NAMES[asked].line}.` }
    await setAvatar($, asked)

    return { text: `Sprout is now ${withArticle(formName(asked, stage))}, of the ${NAMES[asked].line}.` }
  })

  // After each turn the engine measures the session: the context fill picks the stage.
  on('session.measure', async ($, e, next) => {
    const measured = await next(e)
    if (e.changed.includes('context')) await setContext($, e.context.percent)

    return measured
  }).catch(($, e, next) => next(e))

  // A compaction shrinks the context at once, before the next turn measures it.
  on('session.compact', async ($, e, next) => {
    const compacted = await next(e)
    const after = 'skip' in compacted ? undefined : compacted.tokensAfter
    if (e.agentId !== undefined || e.trigger === 'precompute' || after === undefined) return compacted
    const { window } = (await $.session.usage()).context
    if (window > 0) await setContext($, (after / window) * 100)

    return compacted
  }).catch(($, e, next) => next(e))

  // Typing in an idle session: Sprout heads home and looks down at the prompt.
  on('prompt.edit', async ($, e, next) => {
    const edited = await next(e)
    if (isWorking) return edited
    lastEditAt = await $.clock.now()
    const resting = isAsked ? 'awaiting' : 'idle'
    await setActivity($, edited.text.trim() === '' ? resting : 'listening')

    return edited
  }).catch(($, e, next) => next(e))

  on('prompt.submit', async ($, e, next) => {
    isWorking = true
    isAsked = false
    await setReaction($, promptReaction(e.text, await $.clock.now()))
    await setActivity($, 'thinking')

    return next(e)
  }).catch(($, e, next) => next(e))

  on('turn.start', async ($, e, next) => {
    isWorking = true
    streaming = undefined
    await setActivity($, 'thinking')

    return next(e)
  })

  // As the reply streams: thinking blocks keep Sprout thinking, text has it talk.
  on('turn.step', async function* ($, e, next) {
    const isMain = loopOf(e) === undefined
    if (isMain) {
      stepModel = e.model
      if (e.effort !== undefined) stepEffort = { model: canonicalModel(e.model), effort: String(e.effort) }
      void refreshEngine($).catch(() => undefined)
    }
    for await (const chunk of next(e)) {
      if (isMain && chunk.kind === 'thinking' && streaming !== 'thinking') {
        streaming = 'thinking'
        void setActivity($, 'thinking')
      } else if (isMain && chunk.kind === 'text' && streaming !== 'talking') {
        streaming = 'talking'
        void setActivity($, 'talking')
      }
      yield chunk
    }
  })

  on('tool.call', async ($, e, next) => {
    if (loopOf(e) !== undefined) return next(e)
    const doing = toolActivity(String(e.tool))
    streaming = undefined
    await setActivity($, doing)
    const ran = await next(e)
    if (ran.isError) await setReaction($, { kind: 'oops', until: (await $.clock.now()) + 1_500 })
    if (act.kind === doing) await setActivity($, 'thinking')

    return ran
  }).catch(($, e, next) => next(e))

  // A call that needs the person's say-so: Sprout waits with them.
  on('tool.check', async ($, e, next) => {
    const verdict = await next(e)
    if (verdict.decision === 'ask' && loopOf(e) === undefined) await setActivity($, 'asking')

    return verdict
  }).catch(($, e, next) => next(e))

  on('turn.complete', async ($, e, next) => {
    const done = await next(e)
    if (loopOf(e) !== undefined) return done
    isWorking = false
    streaming = undefined
    const after = afterTurn(e.reason, done.text, await $.clock.now())
    isAsked = after.activity === 'awaiting'
    await setReaction($, after.reaction)
    await setActivity($, after.activity)

    return done
  })

  // Sprout stands on the band's bottom row, the line just above the prompt,
  // in a strip as wide as the band so it has room to walk. At the strip's
  // right end, just beside Sprout's home, sits the model and effort label:
  // each half opens the matching built-in picker.
  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    const drawnAvatar = await read($, avatarAtom)
    const drawnStage = await read($, stageAtom)
    if (e.props.hasSurvey || e.props.maxRows < rowsOf(drawnAvatar) || e.props.bodyColumns < MIN_WIDTH) return next(e)
    const shownReaction = await read($, reaction)
    const look = lookAt(await read($, activity), shownReaction, await $.clock.now())
    const from = shownReaction?.from
    const running = await read($, engine)
    // Unset where caffeinate is not loaded, and so no cup.
    const coffee = cupOf((await $.state.get(caffeine).catch(() => undefined))?.value)
    const { Box, Button, Text } = $.ui.resolve(e)
    // What other plugins draw in the band (the task and session lines) goes
    // above the strip, so Sprout keeps the row just above the prompt.
    const below = await next(e)
    const stacked = (strip: RenderElement) =>
      below.type === 'engine' ? (
        strip
      ) : (
        <Box flexDirection="column">
          {below}
          {strip}
        </Box>
      )
    const hasLabel = e.props.bodyColumns >= MIN_WIDTH + LABEL_W
    const { meter, color } = effortMeter(running.effort)
    const pick = (command: 'model' | 'effort') => () =>
      void $.command
        .run({ command })
        .then(() => {
          if (command === 'effort') stepEffort = undefined
          return refreshEngine($)
        })
        .catch(() => undefined)
    const label = hasLabel && (
      <Box flexDirection="column" width={LABEL_W} paddingLeft={1}>
        {coffee && (
          <Text color={coffee.color} dimColor={coffee.isDim} wrap="truncate-end">
            {coffee.text}
          </Text>
        )}
        <Button key="model" plain onPress={pick('model')}>
          <Text color="#5fb44a" bold>
            {modelLabel(running.model)}
          </Text>
        </Button>
        <Button key="effort" plain dimColor={running.effort === ''} onPress={pick('effort')}>
          {running.effort || 'effort'} <Text color={color}>{meter}</Text>
        </Button>
      </Box>
    )

    // No Raster here: the strip is an SVG that plays its own loop of the
    // terminal's walk and poses, so it moves with no redraws, and sits at the
    // band's right end as the terminal's does.
    if (e.surface !== 'terminal') {
      isAnimating = false
      const { Svg } = $.ui.resolve(e)
      const stripW = Math.max(MIN_WIDTH, Math.min(SVG_MAX_W, e.props.bodyColumns - (hasLabel ? LABEL_W : 0)))
      nudge = nudgeOf((await $.state.get(hubCounts).catch(() => undefined))?.value)
      return stacked(
        <Box flexDirection="row" alignItems="flex-end" justifyContent="flex-end" width="100%">
          <Svg
            source={flipbook(stripW, look, nudge, Math.random, drawnAvatar, drawnStage, from)}
            alt={`Sprout the ${formName(drawnAvatar, drawnStage)}, ${look}`}
            width={stripW * SVG_SCALE}
            height={heightOf(drawnAvatar) * SVG_SCALE}
            isInteractive
          />
          {label}
        </Box>,
      )
    }

    const { Raster } = $.ui.resolve(e)
    bandId = e.requestId
    // First drawn, or at home when the band changed width: stand at its new home.
    const wasHome = walk.x < 0 || walk.x === homeOf(width, avatar, stage)
    width = Math.min(512, e.props.bodyColumns - (hasLabel ? LABEL_W : 0))
    avatar = drawnAvatar
    stage = drawnStage
    const home = homeOf(width, avatar, stage)
    walk = wasHome ? { x: home, target: home, facing: -1 } : { x: Math.min(walk.x, home), target: Math.min(walk.target, home), facing: walk.facing }
    isAnimating = true
    nudge = nudgeOf((await $.state.get(hubCounts).catch(() => undefined))?.value)
    lastCells = avatarCells(avatar, stage, width, walk.x, look, tick, strideOf(walk), nudge, from)

    return stacked(
      <Box flexDirection="row" alignItems="flex-end">
        <Raster key={AVATAR} columns={width} rows={rowsOf(avatar)} cells={lastCells} />
        {label}
      </Box>,
    )
  })
}

