import type { Avatar, Form, Stage } from '../types'
import type { Nudge } from './hub'
import { TALL_H, tallMoves, tallPixels, tallStill, tallWidth } from './lines'
import type { Look } from './mood'
import { Canvas, FORM_MOVES, PX_H, cellsOf, effectAt, stagePixels } from './sprite'
import type { Stride } from './sprite'
import { fadeOf, homeFor, nextTeleport, nextWalk } from './walk'
import type { Walk } from './walk'

// Which line Sprout is drawn as, and everything that depends on it: how tall
// the strip is, where home is, how he gets about, and the pixels for a
// moment. The Toad line is sprite.ts; the tall lines are lines.ts.

export const AVATARS: readonly Avatar[] = ['toad', 'lizard', 'fox']
const FORMS: readonly [Form, Form, Form] = ['sprout', 'bud', 'bloom']

/** What Sprout changes from while evolving: an earlier stage, or the last avatar. */
export type From = { avatar: Avatar; stage: Stage }

export const isAvatar = (value: unknown): value is Avatar => AVATARS.includes(value as Avatar)

export function formOf(stage: Stage): Form {
  return FORMS[stage]
}

/** The moves a form attacks with, in turn, when another session has finished. */
export function movesOf(avatar: Avatar, stage: Stage): readonly string[] {
  return avatar === 'toad' ? FORM_MOVES[formOf(stage)] : tallMoves(avatar, stage)
}

/** Pixels down the strip: the Toad line 8, the tall lines 12. */
export function heightOf(avatar: Avatar): number {
  return avatar === 'toad' ? PX_H : TALL_H
}

/** Terminal rows the strip takes, two pixels a row. */
export function rowsOf(avatar: Avatar): number {
  return heightOf(avatar) / 2
}

/** Home on a strip this wide: the right end, the whole form on the strip. */
export function homeOf(width: number, avatar: Avatar, stage: Stage): number {
  return avatar === 'toad' ? homeFor(width, formOf(stage)) : Math.max(0, width - tallWidth(avatar, stage))
}

/** One tick of getting about: the Fox line teleports, the others walk. */
export function stepWalk(avatar: Avatar, walk: Walk, look: Look, tick: number, home: number, chance: number, spot: number): Walk {
  return avatar === 'fox' ? nextTeleport(walk, look, tick, home, chance, spot) : nextWalk(walk, look, tick, home, chance, spot)
}

/** How Sprout is moving, from his walk. */
export function strideOf(walk: Walk): Stride {
  const fade = fadeOf(walk)
  return { isWalking: walk.x !== walk.target && walk.blink === undefined, facing: walk.facing, ...(fade === undefined ? {} : { fade }) }
}

/** Front-on and still, eyes closed: what an evolution's silhouette is cut from. */
function stillOf(avatar: Avatar, stage: Stage, width: number, x: number): string[] {
  // Tick 0 of Sprout's idle is a blink.
  return avatar === 'toad' ? stagePixels(width, x, 'idle', 0, undefined, 'none', formOf(stage)) : tallStill(avatar, stage, width, x)
}

/** The strip's pixel rows for a moment: Sprout at `x` as `avatar` at `stage`. */
export function avatarPixels(
  avatar: Avatar,
  stage: Stage,
  width: number,
  x: number,
  look: Look,
  tick: number,
  stride: Stride = { isWalking: false, facing: 1 },
  nudge: Nudge = 'none',
  from?: From,
): string[] {
  if (look === 'evolving' && from && !(avatar === 'toad' && from.avatar === 'toad')) {
    // A white silhouette flickering between what he was and what he is now,
    // each the same distance from its own home, standing on the same line.
    const height = heightOf(avatar)
    const shown = Math.floor(tick / 2) % 2 === 0 ? from : { avatar, stage }
    const offset = x - homeOf(width, avatar, stage)
    const rows = stillOf(shown.avatar, shown.stage, width, homeOf(width, shown.avatar, shown.stage) + offset)
    const c = new Canvas(width, height)
    c.stamp(0, height - rows.length, rows.map(row => row.replace(/[^.]/g, 'W')))
    const wide = avatar === 'toad' ? 10 : tallWidth(avatar, stage)
    effectAt(c, 'sparkles', x, height - 8, tick, x + wide + 7 <= width ? 1 : -1, wide, height - 8)
    return c.rows()
  }
  if (avatar === 'toad') return stagePixels(width, x, look, tick, stride, nudge, formOf(stage), from && formOf(from.stage))

  return tallPixels(avatar, stage, width, x, look, tick, stride, nudge)
}

/** The same moment as a Raster's cells. */
export function avatarCells(...args: Parameters<typeof avatarPixels>): string {
  return cellsOf(avatarPixels(...args), args[2])
}

