/**
 * The caffeinate mod's hold, as much of its contract as the cup draws. Sprout
 * only reads it, and where caffeinate is not loaded nothing is ever written,
 * so no cup shows.
 */
export type Caffeine = {
  isAwake: boolean
  minutes: number
  source: 'ac' | 'battery' | 'unknown'
  battery: number | null
  isHeldBack: boolean
}

declare module 'claude-code' {
  interface PluginState {
    caffeinate: { caffeine: Caffeine }
  }
}

const BROWN = '#c08552'

export type Cup = { text: string; color: string; isDim: boolean }

/**
 * The line above the model label while the Mac is held awake: `☕ 12m`, with
 * the charge on battery (`☕ 1h04m · 64%`), dimmed and paused when a low
 * battery made caffeinate let go. Null while nothing is held.
 */
export function cupOf(caffeine: Caffeine | undefined): Cup | null {
  if (!caffeine) return null
  if (caffeine.isHeldBack) return { text: `☕ paused · ${caffeine.battery ?? '?'}%`, color: BROWN, isDim: true }
  if (!caffeine.isAwake) return null
  const { minutes } = caffeine
  const time =
    minutes < 1 ? '<1m' : minutes < 60 ? `${minutes}m` : `${Math.floor(minutes / 60)}h${String(minutes % 60).padStart(2, '0')}m`
  const charge = caffeine.source === 'battery' && caffeine.battery !== null ? ` · ${caffeine.battery}%` : ''

  return { text: `☕ ${time}${charge}`, color: BROWN, isDim: false }
}

