/**
 * The session hub's counts, as much of its contract as Sprout's nudge reads.
 * Sprout only reads them; where session-hub is not loaded nothing is written,
 * so there is no nudge.
 */
export type HubCounts = { needs: number; turn: number; working: number; idle: number; stale: number }

declare module 'claude-code' {
  interface PluginState {
    'session-hub': { counts: HubCounts }
  }
}

/** What another session wants from you, as Sprout signals it: a `!`, a ✓, or nothing. */
export type Nudge = 'needs' | 'turn' | 'none'

export function nudgeOf(counts: HubCounts | undefined): Nudge {
  if (!counts) return 'none'
  if (counts.needs > 0) return 'needs'

  return counts.turn > 0 ? 'turn' : 'none'
}

