/** The levels `/effort` takes, lowest first. */
export const EFFORTS = ['low', 'medium', 'high', 'xhigh', 'max'] as const

const EFFORT_COLORS = ['#6cc4a1', '#5fb44a', '#ffd23f', '#f0913a', '#e53935'] as const

/** `claude-opus-5-5[1m]` → `claude-opus-5-5`, the key settings file models under. */
export function canonicalModel(id: string): string {
  const found = /(opus|sonnet|haiku|fable)[- ]?(\d+)(?:[-.](\d+))?/i.exec(id)
  if (!found) return id.trim()
  const [, family = '', major = '', minor] = found

  return `claude-${family.toLowerCase()}-${major}${minor ? `-${minor}` : ''}`
}

/** `claude-opus-5-5` → `Opus 5.5`; anything unrecognised as given. */
export function modelLabel(id: string): string {
  const found = /(opus|sonnet|haiku|fable)[- ]?(\d+)(?:[-.](\d+))?/i.exec(id)
  if (!found) return id.trim() || 'model'
  const [, family = '', major = '', minor] = found

  return `${family.charAt(0).toUpperCase()}${family.slice(1).toLowerCase()} ${major}${minor ? `.${minor}` : ''}`
}

/** The effort the settings give a model: its own entry, else the top-level one. */
export function settingsEffort(settings: Readonly<Record<string, unknown>>, model: string): string {
  const perModel = settings.modelSettings as Record<string, { effortLevel?: unknown } | undefined> | undefined
  const own = perModel?.[canonicalModel(model)]?.effortLevel
  if (typeof own === 'string') return own
  const top = settings.effortLevel

  return typeof top === 'string' ? top : ''
}

/** A five-step meter for a level, and the colour it is drawn in. */
export function effortMeter(effort: string): { meter: string; color: string } {
  const step = EFFORTS.indexOf(effort as (typeof EFFORTS)[number])
  if (step < 0) return { meter: '', color: '#9aa4ad' }

  return { meter: '▮'.repeat(step + 1) + '▯'.repeat(EFFORTS.length - step - 1), color: EFFORT_COLORS[step] ?? '#9aa4ad' }
}

