import type { Avatar, Stage } from '../types'
import { formName, withArticle } from './names'

/** Context fill, in percent of the model's window, at which Sprout evolves: to the second form, then the third. */
export const SECOND_AT = 40
export const THIRD_AT = 75
/** How long the evolution plays. */
export const EVOLVE_MS = 2_800

/** The stage for a context fill; no reading yet is a fresh session. */
export function stageFor(percent: number | undefined): Stage {
  const fill = percent ?? 0
  if (fill >= THIRD_AT) return 2

  return fill >= SECOND_AT ? 1 : 0
}

/** What the toast says when the stage changes: up as the context fills, back down after /compact or /clear. */
export function evolutionToast(avatar: Avatar, from: Stage, to: Stage, percent: number | undefined): string {
  const fill = `${Math.round(percent ?? 0)}%`
  const name = formName(avatar, to)
  if (to < from) return `Sprout is ${withArticle(name)} again: context down to ${fill}`
  if (to === 2) return `Sprout evolved into ${name}: context ${fill} full. A good time to /compact or start fresh`

  return `Sprout evolved into ${name}: context ${fill} full`
}

