import type { Activity, ActivityKind, Reaction } from '../types'

/** What Sprout looks like right now: a reaction while it lasts, else the activity. */
export type Look = ActivityKind | Reaction['kind']

export const SLEEP_AFTER_MS = 180_000
export const LISTEN_FOR_MS = 4_000

/** What a tool call has Sprout do. */
export function toolActivity(tool: string): ActivityKind {
  switch (tool) {
    case 'Read':
    case 'Grep':
    case 'Glob':
    case 'WebFetch':
    case 'WebSearch':
      return 'reading'
    case 'Edit':
    case 'MultiEdit':
    case 'Write':
    case 'NotebookEdit':
      return 'writing'
    case 'Agent':
    case 'Task':
      return 'delegating'
    case 'AskUserQuestion':
      return 'awaiting'
  }

  return 'running'
}

/** How Sprout greets a prompt, by what it says. */
export function promptReaction(text: string, now: number): Reaction {
  const said = text.toLowerCase()
  if (/\b(thanks|thank you|cheers|great job|nice|awesome|love it|perfect|brilliant)\b/.test(said)) {
    return { kind: 'happy', until: now + 2_200 }
  }
  if (/\b(bug|error|broken|fails?|failing|crash(es|ed)?|wrong)\b/.test(said)) return { kind: 'determined', until: now + 1_800 }
  if (/\?\s*$/.test(text.trim())) return { kind: 'curious', until: now + 1_800 }

  return { kind: 'excited', until: now + 1_600 }
}

export type TurnEnd = 'answer' | 'aborted' | 'refusal' | 'error'

/** How Sprout takes the end of a turn. */
export function finishReaction(reason: TurnEnd, now: number): Reaction {
  switch (reason) {
    case 'answer':
      return { kind: 'celebrate', until: now + 2_600 }
    case 'aborted':
      return { kind: 'startled', until: now + 2_000 }
    case 'refusal':
    case 'error':
      return { kind: 'oops', until: now + 3_500 }
  }
}

/** Whether a reply ends by asking the person something. */
export function asksQuestion(text: string): boolean {
  const last = text.trim().split(/\n\s*\n/).pop()?.trim() ?? ''

  return /\?[\s"'”’)*_`]*$/.test(last)
}

/**
 * Where a finished turn leaves Sprout: waiting on the person when the reply
 * ends with a question, else idle after the turn's own reaction.
 */
export function afterTurn(reason: TurnEnd, text: string, now: number): { activity: ActivityKind; reaction: Reaction | null } {
  if (reason === 'answer' && asksQuestion(text)) return { activity: 'awaiting', reaction: null }

  return { activity: 'idle', reaction: finishReaction(reason, now) }
}

/**
 * The look for this moment: a reaction until it lapses, sleep after a long
 * idle. An activity with no start time (`since` 0, before the session began)
 * never counts as a long idle.
 */
export function lookAt(activity: Activity, reaction: Reaction | null, now: number): Look {
  if (reaction && now < reaction.until) return reaction.kind
  if (activity.kind === 'idle' && activity.since > 0 && now - activity.since > SLEEP_AFTER_MS) return 'sleeping'

  return activity.kind
}

