import type { Avatar, Stage } from '../types'
import { avatarPixels, homeOf, stepWalk, strideOf } from './avatar'
import type { From } from './avatar'
import type { Nudge } from './hub'
import type { Look } from './mood'
import { SVG_LIMIT, flipbookSvg } from './sprite'
import type { Walk } from './walk'

/** Ticks of the frame clock a desktop loop plays before Sprout heads home. */
export const LOOP_TICKS = 96
/** The most a loop runs on past its ticks to get home: a whole strip, walking. */
const HOMEWARD_MAX = 200

/**
 * Sprout's next few seconds as the terminal would play them, for a surface
 * with no Raster: the same walk (or teleports) and poses, tick by tick, from
 * home and back to home so the loop has no seam. `random` is passed in so it
 * can be tested.
 */
export function flipbookFrames(
  width: number,
  look: Look,
  nudge: Nudge,
  ticks: number,
  random: () => number,
  avatar: Avatar = 'toad',
  stage: Stage = 0,
  from?: From,
): string[][] {
  const home = homeOf(width, avatar, stage)
  let walk: Walk = { x: home, target: home, facing: -1 }
  const frames: string[][] = []
  for (let tick = 0; tick < ticks || ((walk.x !== home || walk.blink !== undefined) && tick < ticks + HOMEWARD_MAX); tick++) {
    // Past its ticks the loop heads home as if listening: walking back, or one teleport.
    walk = tick < ticks ? stepWalk(avatar, walk, look, tick, home, random(), random()) : stepWalk(avatar, walk, 'listening', tick, home, 0.5, 0.5)
    frames.push(avatarPixels(avatar, stage, width, walk.x, look, tick, strideOf(walk), nudge, from))
  }

  return frames
}

/** The loop as an SVG, shortened until its markup fits what an Svg may hold. */
export function flipbook(
  width: number,
  look: Look,
  nudge: Nudge,
  random: () => number = Math.random,
  avatar: Avatar = 'toad',
  stage: Stage = 0,
  from?: From,
): string {
  for (let ticks = LOOP_TICKS; ; ticks = Math.floor(ticks / 2)) {
    const svg = flipbookSvg(width, flipbookFrames(width, look, nudge, ticks, random, avatar, stage, from))
    if (svg.length < SVG_LIMIT || ticks <= 1) return svg
  }
}

