import type { Avatar, Stage } from '../types'

/**
 * Every name Sprout shows, in one place: each line's name, its three forms,
 * and its moves. Renaming a line or a form is an edit here alone; the ids
 * (`toad`, `lizard`, `fox`) are what /avatar takes and what is stored.
 */
export const NAMES: Readonly<Record<Avatar, { line: string; forms: readonly [string, string, string] }>> = {
  toad: { line: 'Toad line', forms: ['Sprout', 'Bud', 'Bloom'] },
  lizard: { line: 'Lizard line', forms: ['Spark', 'Blaze', 'Inferno'] },
  fox: { line: 'Fox line', forms: ['Doze', 'Spoon', 'Sage'] },
}

export const MOVE_NAMES: Readonly<Record<string, string>> = {
  vine: 'Vine Lash',
  leaf: 'Leaf Volley',
  solar: 'Sunbeam',
  ember: 'Ember',
  flamethrower: 'Flamethrower',
  fireburst: 'Fire Burst',
  teleport: 'Teleport',
  mindbeam: 'Mind Beam',
  mindwave: 'Mind Wave',
}

export function formName(avatar: Avatar, stage: Stage): string {
  return NAMES[avatar].forms[stage]
}

/** `a Spark`, `an Inferno`. */
export function withArticle(name: string): string {
  return `${/^[aeiou]/i.test(name) ? 'an' : 'a'} ${name}`
}

