import type { Form } from '../types'
import type { Nudge } from './hub'
import type { Look } from './mood'

// Sprout, drawn the way Clawd is: flat colour, no outlines and eyes cut out as
// holes, but with four little legs and no arms, and a bulb on top. One pixel is
// one terminal column wide and half a row tall, so Sprout is 10 columns by 4
// rows, standing on the strip's bottom row: the line just above the prompt.
// Effects sit beside Sprout on whichever side has room.

/** Pixels down the strip; the terminal shows two per row. */
export const PX_H = 8
export const ROWS = PX_H / 2
/** Sprout's own width (its body is the middle 8), and the narrowest strip it is drawn in. */
export const BODY_W = 10
export const MIN_WIDTH = 24
/** Columns an effect beside Sprout may reach, counted from Sprout's left edge. */
const EFFECT_REACH = BODY_W + 7
/** Where an effect beside Sprout starts, a column clear of it. */
const BESIDE = BODY_W + 1
export const FRAME_MS = 120

const COLORS: Readonly<Record<string, number>> = {
  T: 0x6cc4a1, // body
  G: 0x5fb44a, // bulb
  L: 0x8fdc6a, // bulb, glowing
  g: 0x3e8a32, // bulb seam
  y: 0xffd23f, // sparkle, alert
  b: 0x6ec6ff, // sweat
  z: 0xb7c3ff, // sleep
  w: 0xcfd6dd, // thought
  p: 0xff7a9a, // heart
  W: 0xf4f6f8, // speech bubble
  o: 0xd97757, // question mark, Clawd's orange
  P: 0xf27fa0, // bud and petals (Bud, Bloom)
  Q: 0xffb8cc, // bud and petals, glowing
  S: 0xfde9ee, // petal spots
  V: 0x2f6e2a, // palm leaves (Bloom)
  // The tall lines (lines.ts).
  O: 0xf08a3c, // Spark, Inferno
  n: 0xc8642a, // their shade: feet, wing bones
  M: 0xd2463a, // Blaze
  m: 0xa3322a, // its shade
  C: 0xf8d898, // belly
  U: 0x3fa3a8, // Inferno's wing membrane
  R: 0xe8402a, // flame, outer; Spoon's star
  F: 0xff8c1a, // flame
  Y: 0xffd23f, // flame core
  A: 0xe9b83a, // Doze, Spoon, Sage
  a: 0xb8862a, // their shade: whiskers, inner ears
  B: 0x8a5634, // their brown armour
  k: 0xc9d1d8, // spoons
  h: 0xf07ad0, // psychic, pink
  v: 0x9b6bff, // psychic, violet
}

// The bulb sits on the head, its base as wide as the head, so the teal starts
// at the eyes and Sprout is mostly face and bulb.
const BULB = ['....GG....', '..GgGGgG..', '.GgGGGGgG.']
// Bud: the bulb opened into a pink bud in green sepals, two leaves
// spread either side and drooping past the body. Twelve wide, from x - 1.
const BUD = ['.....PP.....', '....PPPP....', '...gGPPGg...', 'GGgGGGGGGgGG', 'L..........L']
// Bloom: the bud in full flower, white-spotted petals over a ring of palm leaves.
const FLOWER = ['.PP.PPPP.PP.', 'PSPPPyyPPPSP', '.PPPPPPPPPP.', 'VGVGVGGVGVGV', 'V..........V']
const HEAD = ['.TTTTTTTT.', '.TTTTTTTT.', '.TTTTTTTT.']
const LEGS = [1, 3, 6, 8]

// Eye stamps, left eye then right; `.` cuts a hole the background shows in.
const EYES = {
  open: [['T.', 'T.'], ['.T', '.T']],
  blink: [['TT', 'TT'], ['TT', 'TT']],
  shut: [['TT', '..'], ['TT', '..']],
  up: [['T.', 'TT'], ['.T', 'TT']],
  upLeft: [['.T', 'TT'], ['.T', 'TT']],
  upRight: [['T.', 'TT'], ['T.', 'TT']],
  down: [['TT', 'T.'], ['TT', '.T']],
  left: [['.T', '.T'], ['.T', '.T']],
  right: [['T.', 'T.'], ['T.', 'T.']],
  wide: [['..', '..'], ['..', '..']],
  happy: [['..', 'TT'], ['..', 'TT']],
  cross: [['.T', 'T.'], ['T.', '.T']],
} as const
type Eyes = keyof typeof EYES

const BANG = ['y', 'y', '.', 'y']
const QUESTION = ['yy', '.y', 'y.', '..', 'y.']
const SPARK = ['.y.', 'yyy', '.y.']
const HEART = ['p.p', 'ppp', '.p.']
const ZED = ['zz.', '.z.', '.zz']
const DROP = ['b', 'b']
// Each form side-on, facing right (mirrored to face left), as it turns to
// attack: what grows on its back, one eye cut out, the snout forward, legs.
const SIDE = ['..........', '...GG.....', '..GgGG....', '.GgGGgG...', '.TTTTTTTT.', '.TTTTTT.TT', '.TTTTTTTTT', '..T.T.T.T.']
const SIDE_BUD = ['..PP......', '.PPPP.....', '.gPPgG....', 'GGgGGgGG..', 'LTTTTTTTT.', '.TTTTTT.TT', '.TTTTTTTTT', '..T.T.T.T.']
const SIDE_FLOWER = ['PP.PP.....', 'PSPPSPP...', 'PPPPPPPP..', 'VGVGVGVGV.', 'VTTTTTTTT.', '.TTTTTT.TT', '.TTTTTTTTT', '.TT.T..TT.']

export type { Form }
export type Move = 'vine' | 'leaf' | 'solar'

/** Each form's crown (front-on, and where it sits), its side-on art, and the moves it attacks with in turn. */
const FORMS: Readonly<Record<Form, { crown: readonly string[]; crownX: number; crownY: number; side: readonly string[]; moves: readonly Move[] }>> = {
  sprout: { crown: BULB, crownX: 0, crownY: 1, side: SIDE, moves: ['vine', 'leaf'] },
  bud: { crown: BUD, crownX: -1, crownY: 0, side: SIDE_BUD, moves: ['vine', 'leaf'] },
  bloom: { crown: FLOWER, crownX: -1, crownY: 0, side: SIDE_FLOWER, moves: ['vine', 'leaf', 'solar'] },
}

/** Columns a form's leaves reach past Sprout's outline on the right, so home stands that much further in. */
export const FORM_OVERHANG: Readonly<Record<Form, number>> = { sprout: 0, bud: 2, bloom: 2 }

export const FORM_MOVES: Readonly<Record<Form, readonly Move[]>> = {
  sprout: FORMS.sprout.moves,
  bud: FORMS.bud.moves,
  bloom: FORMS.bloom.moves,
}

/** Bulb, bud or flower lit up: the greens brighten, and so do the petals. */
function glowing(isOn: boolean): (ch: string) => string {
  return ch => (!isOn ? ch : ch === 'G' ? 'L' : ch === 'P' ? 'Q' : ch)
}
// A leaf volley mid-spin, flat then on its edge, facing right.
const LEAF_FLAT = ['GL']
const LEAF_EDGE = ['.L', 'G.']
// The vine's crack at full reach: sparks round its tip.
const CRACK = ['y.y', '...', 'y.y']
// A speech bubble holding a question mark, its tail pointing back at Sprout.
const BUBBLE = ['WWWWW', 'WoooW', 'WWWoW', 'WWoWW', 'WWWWW', 'WWoWW', 'WWWWW']
// The bubble and its tail fill the strip's full height, so it flashes rather than bobs.

export type Effect = 'none' | 'bang' | 'question' | 'sparkles' | 'hearts' | 'zzz' | 'sweat' | 'dots' | 'ask'

export type Pose = {
  dy: number
  bulbDx: number
  glow: boolean
  legs: readonly [boolean, boolean, boolean, boolean]
  eyes: Eyes
  isMouthOpen: boolean
  effect: Effect
}

/**
 * How Sprout is moving along the line, if at all; `fade` (0 there, 1 gone) is
 * how far through a teleport a line that teleports is.
 */
export type Stride = { isWalking: boolean; facing: -1 | 1; fade?: number }

const STILL: Pose = {
  dy: 0,
  bulbDx: 0,
  glow: false,
  legs: [true, true, true, true],
  eyes: 'open',
  isMouthOpen: false,
  effect: 'none',
}

const HOP = [0, -1, -1, 0]

/** The pose for a look at a tick of the frame clock. */
export function poseFor(look: Look, tick: number): Pose {
  const blinking = tick % 40 < 2
  const swing = tick % 4 < 2
  switch (look) {
    case 'idle':
      return { ...STILL, eyes: blinking ? 'blink' : 'open' }
    case 'sleeping':
      return { ...STILL, eyes: 'shut', effect: 'zzz' }
    case 'listening':
      return { ...STILL, eyes: blinking ? 'blink' : 'down' }
    case 'thinking':
      return { ...STILL, eyes: tick % 24 < 12 ? 'upLeft' : 'upRight', glow: tick % 8 < 4, effect: 'dots' }
    case 'talking':
      return { ...STILL, eyes: blinking ? 'blink' : 'open', isMouthOpen: swing }
    case 'reading':
      return { ...STILL, eyes: tick % 16 < 8 ? 'left' : 'right' }
    case 'writing':
      // Head down, tapping the inner feet as if typing.
      return { ...STILL, eyes: 'down', legs: [true, swing, !swing, true] }
    case 'running':
      return { ...STILL, eyes: 'open' }
    case 'delegating':
      return { ...STILL, eyes: 'up', glow: swing, effect: 'sparkles' }
    case 'asking':
      return { ...STILL, dy: tick % 12 < 2 ? -1 : 0, eyes: 'wide', effect: tick % 6 < 4 ? 'bang' : 'none' }
    case 'awaiting':
      return {
        ...STILL,
        dy: tick % 10 < 2 ? -1 : 0,
        eyes: tick % 24 < 14 ? 'up' : blinking ? 'blink' : 'down',
        effect: 'ask',
      }
    case 'excited':
      return { ...STILL, dy: HOP[tick % HOP.length] ?? 0, eyes: 'happy', isMouthOpen: true }
    case 'happy':
      return { ...STILL, bulbDx: [0, 1, 0, -1][Math.floor(tick / 2) % 4] ?? 0, eyes: 'happy', effect: 'hearts' }
    case 'curious':
      return { ...STILL, bulbDx: 1, eyes: 'up', effect: 'question' }
    case 'determined':
      // Eyes narrowed, stamping the feet.
      return { ...STILL, eyes: 'shut', legs: [swing, !swing, swing, !swing] }
    case 'celebrate':
      return {
        ...STILL,
        dy: HOP[tick % HOP.length] ?? 0,
        eyes: 'happy',
        isMouthOpen: true,
        glow: true,
        effect: 'sparkles',
      }
    case 'oops':
      return { ...STILL, eyes: tick % 20 < 10 ? 'cross' : 'down', effect: 'sweat' }
    case 'startled':
      return { ...STILL, dy: -1, eyes: 'wide', effect: 'bang' }
    case 'evolving':
      // Drawn as a white silhouette flickering between the two forms (stagePixels).
      return { ...STILL, effect: 'sparkles' }
  }
}

/** A pose on the move: legs step in turn, and the eyes look where Sprout is going. */
function stepping(pose: Pose, look: Look, stride: Stride, tick: number): Pose {
  if (!stride.isWalking) return pose
  const step = tick % 4 < 2
  const legs = [step, !step, step, !step] as const
  const isGlancing = look === 'idle' || look === 'running' || look === 'listening'

  return { ...pose, legs, eyes: isGlancing ? (stride.facing < 0 ? 'left' : 'right') : pose.eyes }
}

export class Canvas {
  readonly px: string[][]

  constructor(
    readonly width: number,
    height = PX_H,
  ) {
    this.px = Array.from({ length: height }, () => Array<string>(width).fill('.'))
  }

  rows(): string[] {
    return this.px.map(row => row.join(''))
  }

  put(x: number, y: number, c: string): void {
    const row = this.px[y]
    if (row && x >= 0 && x < this.width) row[x] = c
  }

  /** Pastes rows of pixels; with `clear`, a `.` cuts a hole instead of leaving what is beneath. */
  stamp(x0: number, y0: number, art: readonly string[], clear = false, recolor: (c: string) => string = c => c): void {
    art.forEach((line, dy) => {
      for (let dx = 0; dx < line.length; dx++) {
        const c = line.charAt(dx)
        if (c !== '.' || clear) this.put(x0 + dx, y0 + dy, c === '.' ? c : recolor(c))
      }
    })
  }
}

function effect(c: Canvas, kind: Effect, x: number, y: number, tick: number, side: 1 | -1): void {
  effectAt(c, kind, x, y, tick, side, BODY_W, 0)
}

/**
 * Draws an effect beside a creature `bodyW` wide at `x`. `at(dx, w)` places
 * art `w` wide that sits `dx` columns from its left edge on the right side,
 * or mirrored onto the left when `side` is -1; the art itself is never
 * mirrored. `top` is where the full-height speech bubble starts.
 */
export function effectAt(c: Canvas, kind: Effect, x: number, y: number, tick: number, side: 1 | -1, bodyW: number, top: number): void {
  const BODY_W = bodyW
  const BESIDE = bodyW + 1
  const at = (dx: number, w: number) => (side > 0 ? x + dx : x + BODY_W - dx - w)
  switch (kind) {
    case 'bang':
      return c.stamp(at(BESIDE, 1), y + 1, BANG)
    case 'question':
      return c.stamp(at(BESIDE, 2), y, QUESTION)
    case 'dots': {
      const shown = 1 + (Math.floor(tick / 4) % 3)
      const spots = [[BODY_W, 4], [BESIDE, 2], [BESIDE + 1, 0]] as const
      spots.slice(0, shown).forEach(([dx, dy]) => c.put(at(dx, 1), y + dy, 'w'))
      return
    }
    case 'sparkles': {
      if (Math.floor(tick / 3) % 2 === 0) {
        c.stamp(at(BESIDE, 3), y + 1, SPARK)
        c.put(at(1, 1), y + 1, 'y')
      } else {
        c.stamp(at(BESIDE, 3), y + 4, SPARK)
        c.put(at(BODY_W - 2, 1), y + 1, 'y')
      }
      return
    }
    case 'hearts':
      return c.stamp(at(BESIDE, 3), y + 3 - (Math.floor(tick / 3) % 4), HEART)
    case 'zzz':
      return c.stamp(at(BESIDE, 3), y + 3 - (Math.floor(tick / 5) % 4), ZED)
    case 'sweat':
      return c.stamp(at(BODY_W - 1, 1), y + 2 + (Math.floor(tick / 5) % 2), DROP)
    case 'ask': {
      // The question mark flashes, and the tail points back at Sprout.
      const left = at(BESIDE, 5)
      const flash = (ch: string) => (ch === 'o' && Math.floor(tick / 4) % 3 === 2 ? 'y' : ch)
      c.stamp(left, top, BUBBLE, false, flash)
      c.put(side > 0 ? left : left + 4, top + BUBBLE.length, 'W')
      return
    }
    case 'none':
      return
  }
}

/** Ticks between the starts of two attacks, and how long one lasts. */
export const ATTACK_EVERY = 48
export const ATTACK_TICKS = 16
/** How far a vine reaches, and a leaf volley flies, from Sprout's front. */
const VINE_REACH = 14
const LEAF_REACH = 26
/** How far Sunbeam reaches: across the strip. */
const SOLAR_REACH = 48
/** Leaf Volley's three leaves: the tick each leaves the bulb, and its line. They fly three columns a tick. */
const VOLLEY = [
  { at: 2, dy: 2 },
  { at: 4, dy: 4 },
  { at: 6, dy: 1 },
] as const

export type Attack = { move: Move; t: number }

/**
 * Another session has finished and Sprout has nothing else to do: every few
 * seconds he turns side-on to the open space and attacks it, Vine Lash and
 * Leaf Volley in turn. Between attacks, and while he is walking, none.
 */
export function attackAt(look: Look, nudge: Nudge, tick: number, isWalking: boolean, form: Form = 'sprout'): Attack | undefined {
  if (nudge !== 'turn' || isWalking || (look !== 'idle' && look !== 'listening')) return undefined
  const t = tick % ATTACK_EVERY
  if (t >= ATTACK_TICKS) return undefined
  const { moves } = FORMS[form]

  return { move: moves[Math.floor(tick / ATTACK_EVERY) % moves.length] ?? 'vine', t }
}

export function mirrored(art: readonly string[], facing: 1 | -1): readonly string[] {
  return facing > 0 ? art : art.map(line => [...line].reverse().join(''))
}

/**
 * Sprout side-on at `x`, facing the open space, and the attack's frame `t`.
 * Vine Lash: the bulb glows, two vines lash out, the upper one cracks with a
 * spark at full reach, then both pull back. Leaf Volley: three leaves fly from
 * the bulb, spinning, one after another.
 */
function drawAttack(c: Canvas, attack: Attack, x: number, y: number, facing: 1 | -1, form: Form): void {
  const { move, t } = attack
  const isGlowing = move === 'vine' ? t < 9 : move === 'leaf' ? t < 8 : t < 13
  c.stamp(x, y, mirrored(FORMS[form].side, facing), false, glowing(isGlowing))
  // The first column clear of Sprout's front, and a column `d` further out.
  const front = facing > 0 ? x + BODY_W : x - 1
  const out = (d: number) => front + facing * d

  if (move === 'solar') {
    // Sunbeam: light gathers at the snout, then a beam crosses the strip
    // and thins out.
    if (t < 6) {
      for (let i = 0; i < 3; i++) c.put(out(Math.max(0, (6 - t) * 2 + i * 2 - 2)), y + 2 + i * 2, 'y')
      if (t >= 3) c.put(out(0), y + 4, 'W')
      return
    }
    const reach = Math.min(SOLAR_REACH, (t - 5) * 10)
    for (let d = 0; d < reach; d++) {
      if (t < 15) c.put(out(d), y + 4, 'W')
      if (t < 13 || (t < 14 && d % 2 === 0)) {
        c.put(out(d), y + 3, (d + t) % 4 === 0 ? 'W' : 'y')
        c.put(out(d), y + 5, (d + t) % 4 === 2 ? 'W' : 'y')
      }
    }
    return
  }

  if (move === 'vine') {
    const reach = t < 3 ? 0 : t < 9 ? Math.min(VINE_REACH, (t - 2) * 3) : t < 11 ? VINE_REACH : Math.max(0, VINE_REACH - (t - 10) * 4)
    const isCracking = t === 9 || t === 10
    for (let d = 0; d < reach; d++) {
      // A slight wave down the vine, still at the tip while it cracks.
      const sway = !isCracking && Math.floor((d + t) / 3) % 2 === 1 ? 1 : 0
      const isTip = d === reach - 1
      c.put(out(d), y + 4 + sway - (isCracking && isTip ? 1 : 0), isTip ? 'L' : 'G')
      if (d < reach - 3) c.put(out(d), y + 6, d === reach - 4 ? 'L' : 'g')
    }
    if (isCracking) {
      c.put(out(VINE_REACH), y + 2, 'y')
      if (t === 10) c.stamp(out(VINE_REACH) - 1, y + 1, CRACK)
    }
    return
  }

  for (const { at, dy } of VOLLEY) {
    const flown = (t - at) * 3
    if (t < at || flown >= LEAF_REACH) continue
    const art = mirrored((t - at) % 2 === 0 ? LEAF_FLAT : LEAF_EDGE, facing)
    c.stamp(facing > 0 ? out(flown) : out(flown) - 1, y + dy, art)
  }
}

/** One frame of an attack on its own, for the gallery: `form` at `x`, facing the open space. */
export function attackPixels(width: number, x: number, form: Form, attack: Attack, facing: 1 | -1): string[] {
  const c = new Canvas(width)
  drawAttack(c, attack, x, 0, facing, form)

  return c.px.map(row => row.join(''))
}

/**
 * The nudge for another session, drawn only when Sprout shows no effect of his
 * own: a blinking `!` while one needs you; while one has finished, an attack
 * when he is free (attackAt) and a spinning leaf beside him while he is busy.
 * Idle, he keeps glancing towards it.
 */
function nudged(pose: Pose, look: Look, nudge: Nudge, side: 1 | -1, tick: number): Pose {
  if (nudge === 'none' || pose.effect !== 'none') return pose
  const isGlancing = (look === 'idle' || look === 'listening') && tick % 16 < 8

  return isGlancing ? { ...pose, eyes: side > 0 ? 'right' : 'left' } : pose
}

/** The strip's pixel rows with Sprout standing at column `x`; `.` is see-through. */
export function stagePixels(
  width: number,
  x: number,
  look: Look,
  tick: number,
  stride: Stride = { isWalking: false, facing: 1 },
  nudge: Nudge = 'none',
  form: Form = 'sprout',
  from?: Form,
): string[] {
  const side = x + EFFECT_REACH <= width ? 1 : -1
  if (look === 'evolving') {
    // Evolving: a white silhouette flickering between the old form and the
    // new, in a shower of sparkles; the new form shows once it lapses.
    const shown = from !== undefined && Math.floor(tick / 2) % 2 === 0 ? from : form
    const c = new Canvas(width)
    // Tick 0 of idle is a blink, so the silhouette has no eye holes.
    c.stamp(0, 0, stagePixels(width, x, 'idle', 0, undefined, 'none', shown).map(row => row.replace(/[^.]/g, 'W')))
    effect(c, 'sparkles', x, 0, tick, side)
    return c.px.map(row => row.join(''))
  }
  const own = stepping(poseFor(look, tick), look, stride, tick)
  const pose = nudged(own, look, nudge, side, tick)
  const c = new Canvas(width)
  const y = pose.dy
  const attack = own.effect === 'none' ? attackAt(look, nudge, tick, stride.isWalking, form) : undefined
  if (attack) {
    drawAttack(c, attack, x, y, side, form)
    return c.px.map(row => row.join(''))
  }
  const { crown, crownX, crownY } = FORMS[form]

  c.stamp(x + crownX + pose.bulbDx, y + crownY, crown, false, glowing(pose.glow))
  c.stamp(x, y + 4, HEAD)
  LEGS.forEach((dx, i) => {
    if (pose.legs[i]) c.put(x + dx, y + 7, 'T')
  })
  const [left, right] = EYES[pose.eyes]
  c.stamp(x + 2, y + 4, left, true)
  c.stamp(x + 6, y + 4, right, true)
  if (pose.isMouthOpen) c.stamp(x + 4, y + 6, ['..'], true)
  effect(c, pose.effect, x, y, tick, side)
  if (pose.effect === 'none' && nudge !== 'none') {
    const at = (w: number) => (side > 0 ? x + BESIDE : x + BODY_W - BESIDE - w)
    if (nudge === 'needs' && tick % 8 < 5) c.stamp(at(1), y + 1, BANG)
    if (nudge === 'turn') c.stamp(at(2), y + 2 + (Math.floor(tick / 6) % 2), mirrored(tick % 8 < 4 ? LEAF_FLAT : LEAF_EDGE, side))
  }

  return c.px.map(row => row.join(''))
}

const ALPHABET = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'
const DEFAULT_COLOR = 0x01000000

function base64(bytes: Uint8Array): string {
  const out: string[] = []
  for (let i = 0; i < bytes.length; i += 3) {
    const [a = 0, b, c] = [bytes[i], bytes[i + 1], bytes[i + 2]]
    const n = (a << 16) | ((b ?? 0) << 8) | (c ?? 0)
    out.push(
      ALPHABET.charAt((n >> 18) & 63),
      ALPHABET.charAt((n >> 12) & 63),
      b === undefined ? '=' : ALPHABET.charAt((n >> 6) & 63),
      c === undefined ? '=' : ALPHABET.charAt(n & 63),
    )
  }

  return out.join('')
}

function colorOf(rows: readonly string[], x: number, y: number): number | undefined {
  const c = rows[y]?.charAt(x) ?? '.'

  return c === '.' ? undefined : COLORS[c]
}

/**
 * Pixel rows as a Raster's cells, two pixels a row: `▀` with the upper pixel
 * as foreground and the lower as background, `▄` where only the lower is
 * drawn, else blank.
 */
export function cellsOf(pixels: readonly string[], width: number): string {
  const rows = Math.ceil(pixels.length / 2)
  const view = new DataView(new ArrayBuffer(width * rows * 12))
  for (let row = 0; row < rows; row++) {
    for (let col = 0; col < width; col++) {
      const top = colorOf(pixels, col, row * 2)
      const bottom = colorOf(pixels, col, row * 2 + 1)
      const cell =
        top !== undefined
          ? [0x2580, top, bottom ?? DEFAULT_COLOR]
          : bottom !== undefined
            ? [0x2584, bottom, DEFAULT_COLOR]
            : [0x20, DEFAULT_COLOR, DEFAULT_COLOR]
      cell.forEach((word, i) => view.setUint32(((row * width + col) * 3 + i) * 4, word, true))
    }
  }

  return base64(new Uint8Array(view.buffer))
}

/** The strip as a Raster's cells, Sprout standing at column `x`. */
export function stageCells(
  width: number,
  x: number,
  look: Look,
  tick: number,
  stride?: Stride,
  nudge: Nudge = 'none',
  form: Form = 'sprout',
  from?: Form,
): string {
  return cellsOf(stagePixels(width, x, look, tick, stride, nudge, form, from), width)
}

/** Pixel rows as SVG paths, one per colour, each pixel one unit square. */
function pathsOf(rows: readonly string[]): string {
  const paths = new Map<string, string[]>()
  rows.forEach((line, y) => {
    for (let x = 0; x < line.length; ) {
      const c = line.charAt(x)
      let end = x + 1
      while (line.charAt(end) === c) end++
      if (c !== '.') paths.set(c, [...(paths.get(c) ?? []), `M${x} ${y}h${end - x}v1h${x - end}z`])
      x = end
    }
  })

  return [...paths]
    .map(([c, d]) => `<path fill="#${(COLORS[c] ?? 0).toString(16).padStart(6, '0')}" d="${d.join('')}"/>`)
    .join('')
}

/** CSS pixels per Sprout pixel where it is drawn as an SVG. */
export const SVG_SCALE = 6
/** The most an Svg's markup may hold. */
export const SVG_LIMIT = 131_072

function svgOf(width: number, body: string, height = PX_H): string {
  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${width} ${height}" width="${width * SVG_SCALE}" height="${height * SVG_SCALE}" shape-rendering="crispEdges">${body}</svg>`
}

/** Sprout alone as an SVG, for the surfaces with no Raster. */
export function spriteSvg(look: Look, tick: number): string {
  return svgOf(MIN_WIDTH, pathsOf(stagePixels(MIN_WIDTH, 1, look, tick)))
}

/**
 * A strip as an SVG that plays itself: one group per run of identical frames,
 * each shown for its share of the loop by a discrete SMIL animation, so a
 * surface with no Raster animates Sprout with no redraws. The first frame is
 * what shows where SMIL does not run.
 */
export function flipbookSvg(width: number, frames: readonly (readonly string[])[]): string {
  const height = frames[0]?.length ?? PX_H
  const runs: { rows: readonly string[]; from: number; to: number }[] = []
  frames.forEach((rows, i) => {
    const last = runs[runs.length - 1]
    if (last && last.rows.join('\n') === rows.join('\n')) last.to = i + 1
    else runs.push({ rows, from: i, to: i + 1 })
  })
  if (runs.length <= 1) return svgOf(width, pathsOf(runs[0]?.rows ?? []), height)

  const at = (i: number) => String(Number((i / frames.length).toFixed(4)))
  const dur = frames.length * FRAME_MS
  const groups = runs.map(({ rows, from, to }) => {
    const [values, keyTimes] =
      from === 0 ? ['1;0', `0;${at(to)}`] : to === frames.length ? ['0;1', `0;${at(from)}`] : ['0;1;0', `0;${at(from)};${at(to)}`]
    const animate = `<animate attributeName="opacity" calcMode="discrete" dur="${dur}ms" repeatCount="indefinite" values="${values}" keyTimes="${keyTimes}"/>`

    return `<g opacity="${from === 0 ? 1 : 0}">${animate}${pathsOf(rows)}</g>`
  })

  return svgOf(width, groups.join(''), height)
}

