import type { Look } from './mood'
import { BODY_W, FORM_OVERHANG } from './sprite'
import type { Form } from './sprite'

/** Where Sprout stands and is heading; `blink` counts down a teleport (8 to 1) for a line that teleports. */
export type Walk = { x: number; target: number; facing: -1 | 1; blink?: number }

/**
 * The furthest column Sprout's left edge may reach on a strip this wide: its
 * body (one column in from the sprite's edges) ending on the strip's last
 * column, beside the label there.
 */
export function maxXFor(width: number): number {
  return Math.max(0, width - BODY_W + 1)
}

/** Home on a strip this wide for a form: the right end, clear of its leaves. */
export function homeFor(width: number, form: Form = 'sprout'): number {
  return Math.max(0, maxXFor(width) - FORM_OVERHANG[form])
}

/**
 * Where Sprout heads next, one tick at a time. Home is the right end of the
 * line, at `maxX`, just above the prompt. Running paces the whole line,
 * thinking shuffles to and fro, idling wanders a little way left of home and
 * drifts back, and listening, sleeping and waiting on an answer go home;
 * anything else stands still. `chance` and `spot` are random numbers in
 * [0, 1), passed in so the walk can be tested.
 */
export function nextWalk(walk: Walk, look: Look, tick: number, maxX: number, chance: number, spot: number): Walk {
  const clamp = (x: number) => Math.max(0, Math.min(maxX, x))
  const home = maxX
  const x = clamp(walk.x)
  let target = clamp(walk.target)
  const isThere = x === target
  let isQuick = false

  switch (look) {
    case 'running':
      isQuick = true
      if (isThere) target = Math.floor(spot * (maxX + 1))
      break
    case 'thinking':
      if (isThere && chance < 0.05) target = clamp(x + (spot < 0.5 ? -3 : 3))
      break
    case 'idle':
      if (isThere && chance < 0.012) target = clamp(home - Math.floor(spot * 22))
      else if (isThere && x !== home && chance < 0.05) target = home
      break
    case 'listening':
    case 'sleeping':
    case 'awaiting':
      target = home
      break
    default:
      target = x
  }

  if (x === target || (!isQuick && tick % 2 === 1)) return { x, target, facing: walk.facing }
  const facing = target < x ? -1 : 1

  return { x: x + facing, target, facing }
}

/** Ticks a teleport takes: half fading out where it was, half fading in where it went. */
const BLINK = 8

/**
 * As nextWalk, for a line that teleports: rather than stepping, it fades out
 * where it is and in where it was heading, then waits there as a walker
 * would. Running, it keeps hopping round the line.
 */
export function nextTeleport(walk: Walk, look: Look, tick: number, maxX: number, chance: number, spot: number): Walk {
  if (walk.blink !== undefined) {
    const blink = walk.blink - 1
    if (blink <= 0) return { x: walk.target, target: walk.target, facing: walk.facing }
    return { ...walk, x: blink === BLINK / 2 ? walk.target : walk.x, blink }
  }
  const next = nextWalk(walk, look, tick, maxX, chance, spot)
  if (next.target === walk.x || next.x === walk.x) return { ...next, x: walk.x }

  return { x: walk.x, target: next.target, facing: next.facing, blink: BLINK }
}

/** How far through a teleport: 0 there, 1 gone; undefined when not teleporting. */
export function fadeOf(walk: Walk): number | undefined {
  if (walk.blink === undefined) return undefined
  return walk.blink > BLINK / 2 ? (BLINK + 1 - walk.blink) / (BLINK / 2) : (walk.blink - 1) / (BLINK / 2)
}

