  wide: 18,
  moves: ['mindbeam', 'mindwave'],
  spoons: [{ x: 1, y: 9 }, { x: 0, y: 10 }, { x: 1, y: 10 }, { x: 13, y: 9 }, { x: 13, y: 10 }, { x: 14, y: 10 }],
  focus: { x: 7, y: 4 },
  isFloating: true,
}

const LINES: Readonly<Record<TallLine, readonly [Creature, Creature, Creature]>> = {
  lizard: [spark, blaze, inferno],
  fox: [doze, spoon, sage],
}

/** How wide a tall form is drawn, so home stands it at the strip's right end. */
export function tallWidth(line: TallLine, stage: number): number {
  return LINES[line][stage]?.wide ?? 16
}

export function tallMoves(line: TallLine, stage: number): readonly TallMove[] {
  return LINES[line][stage]?.moves ?? []
}

/** How long each move takes, in ticks; all start and end inside one ATTACK_EVERY. */
const MOVE_TICKS: Readonly<Record<TallMove, number>> = {
  ember: 22,
  flamethrower: 22,
  fireburst: 26,
  teleport: 18,
  mindbeam: 22,
  mindwave: 24,
}

export type TallAttack = { move: TallMove; t: number }

/** As the Toad line's attackAt: another session finished and this one is free, so every few seconds an attack. */
export function tallAttackAt(line: TallLine, stage: number, look: Look, nudge: Nudge, tick: number, isWalking: boolean): TallAttack | undefined {
  if (nudge !== 'turn' || isWalking || (look !== 'idle' && look !== 'listening')) return undefined
  const moves = tallMoves(line, stage)
  const move = moves[Math.floor(tick / ATTACK_EVERY) % moves.length]
  const t = tick % ATTACK_EVERY
  if (!move || t >= MOVE_TICKS[move]) return undefined

  return { move, t }
}

/** A fixed scatter, so a teleport dissolves the same way each time. */
function scatter(x: number, y: number): number {
  let h = Math.imul(x + 1, 0x27d4eb2d) ^ Math.imul(y + 7, 0x165667b1)
  h = Math.imul(h ^ (h >>> 15), 0x2c1b3c6d)
  return ((h ^ (h >>> 13)) >>> 0) / 4294967296
}

/** Rows dissolved by `amount` (0 whole, 1 gone), a few pixels left as psychic sparks. */
function dissolve(rows: readonly string[], amount: number, tick: number): string[] {
  return rows.map((row, y) =>
    [...row]
      .map((ch, x) => (ch === '.' || scatter(x, y) >= amount ? ch : scatter(x + tick, y) > 0.86 ? (tick % 2 ? 'h' : 'v') : '.'))
      .join(''),
  )
}

/** Where a flame of `size` sits so its bottom centre matches the form's own. */
function flameBase(creature: Creature, at: Point): Point {
  const art = FLAMES[creature.flame?.size ?? 0]![0]!
  return { x: at.x + Math.floor(art[0]!.length / 2), y: at.y + art.length }
}

function stampFlame(c: Canvas, art: Art, base: Point, facing: 1 | -1): void {
  const w = art[0]!.length
  c.stamp(base.x - Math.floor(w / 2), base.y - art.length, mirrored(art, facing))
}

/**
 * How high the tail flame burns for a look: low asleep or after a slip, high
 * when excited or set on something, as the flame shows the creature's mood.
 */
function flameLevel(creature: Creature, look: Look): number {
  const own = creature.flame?.size ?? 0
  if (look === 'sleeping') return -2
  if (look === 'oops') return -1
  if (look === 'excited' || look === 'celebrate' || look === 'determined' || look === 'evolving') return Math.min(2, own + 1)
  return own
}

function flameArt(level: number, tick: number): Art {
  const frames = level >= 0 ? FLAMES[level]! : LOW_FLAMES[-level - 1]!
  return frames[Math.floor(tick / 2) % 3]!
}

/** How far a form may lift (a hop, a float) before its top would leave the strip. */
function headroom(creature: Creature): number {
  const top = creature.art.findIndex(row => /[^.]/.test(row))
  return Math.max(0, top)
}

/** Front-on at `x`, lifted `dy`, with its eyes, flame and spoons for the look. */
function drawFront(c: Canvas, creature: Creature, x: number, dy: number, look: Look, tick: number, shut: boolean, glow: boolean): void {
  c.stamp(x, dy, creature.art)
  if (shut || creature.isAsleep) for (const { x: ex, y: ey } of creature.eyes) c.put(x + ex, ey + dy, creature.body)
  if (creature.flame) {
    const base = flameBase(creature, { x: x + creature.flame.front.x, y: creature.flame.front.y + dy })
    stampFlame(c, flameArt(flameLevel(creature, look), tick), base, 1)
  }
  if (creature.spoons) {
    const glint = glow ? (tick % 2 === 0 ? 'h' : 'W') : tick % 24 < 2 ? 'W' : 'k'
    for (const { x: sx, y: sy } of creature.spoons) c.put(x + sx, sy + dy, glint)
  }
}

/** Side-on at `x`, facing `facing`, mid-stride on alternate steps: the Lizard line walking or breathing fire. */
function drawSide(c: Canvas, creature: Creature, x: number, facing: 1 | -1, isStep: boolean, tick: number): void {
  const side = creature.side ?? creature.art
  const body = isStep && creature.stepRow ? [...side.slice(0, TALL_H - 1), creature.stepRow] : side
  c.stamp(x, 0, mirrored(body, facing))
  if (creature.flame) {
    const art = flameArt(creature.flame.size, tick)
    const w = art[0]!.length
    const fx = facing > 0 ? creature.flame.side.x : creature.wide - creature.flame.side.x - w
    c.stamp(x + fx, creature.flame.side.y, mirrored(art, facing))
  }
}

const BURST = ['.Y.', 'YRY', '.Y.']
const FIREBALL = [['FY', 'RF'], ['YF', 'FR']]
const BIG_FIREBALL = [['.FY', 'FYW', 'RF.'], ['YF.', 'WYF', '.FR']]
// Fire Burst's burst: an eight-pointed star.
const STAR = ['Y..Y..Y', '.Y.Y.Y.', '..YYY..', 'YYYWYYY', '..YYY..', '.Y.Y.Y.', 'Y..Y..Y']
const PSY = ['h', 'v', 'Y', 'v']

/** One frame of a move, the form at `x` facing the open space. */
function drawAttack(c: Canvas, creature: Creature, attack: TallAttack, x: number, facing: 1 | -1, tick: number): void {
  const { move, t } = attack
  if (move === 'ember' || move === 'flamethrower' || move === 'fireburst') {
    drawSide(c, creature, x, facing, false, tick)
    const mouth = creature.mouth ?? { x: creature.wide - 1, y: 6 }
    const mouthX = facing > 0 ? x + mouth.x : x + creature.wide - 1 - mouth.x
    const out = (d: number) => mouthX + facing * d
    if (move === 'ember') {
      // Three embers, one after another, arcing down as they fly.
      for (const at of [2, 6, 10]) {
        const d = (t - at) * 2
        if (t < at || d > 26) continue
        if (d > 22) c.stamp(out(24) - 1, mouth.y + 2, BURST)
        else c.stamp(out(d) - (facing > 0 ? 0 : 1), mouth.y - 1 + Math.round((d / 12) ** 2), FIREBALL[t % 2]!)
      }
      if (t < 12 && t % 4 < 2) c.put(out(0), mouth.y, 'Y')
    } else if (move === 'flamethrower') {
      // A breath in, then a cone of flame that pours out and pulls away.
      if (t < 3) c.put(out(0), mouth.y, t === 2 ? 'Y' : 'R')
      else {
        const reach = Math.min(26, (t - 2) * 4)
        const gone = t < 16 ? 0 : (t - 15) * 5
        for (let d = gone; d < reach; d++) {
          const spread = Math.min(2, Math.floor(d / 6))
          c.put(out(d), mouth.y, (d + t) % 3 === 0 ? 'W' : 'Y')
          for (let k = 1; k <= spread; k++) {
            if ((d + k + t) % 4 !== 0) c.put(out(d), mouth.y - k, k === spread ? 'R' : 'F')
            if ((d + k * 2 + t) % 4 !== 1) c.put(out(d), mouth.y + k, k === spread ? 'R' : 'F')
          }
        }
      }
    } else {
      // Fire Burst: light gathers, a fireball flies, and bursts into a star.
      const target = 30
      if (t < 4) c.stamp(out(1) - 1, mouth.y - 1, t < 2 ? ['.Y.', 'Y.Y', '.Y.'] : ['.F.', 'FWF', '.F.'])
      else if (t < 11) c.stamp(out(Math.min(target, (t - 4) * 5)) - 1, mouth.y - 1, mirrored(BIG_FIREBALL[t % 2]!, facing))
      else if (t < 24) {
        const hue = (ch: string) => (ch === 'Y' ? (['Y', 'F', 'W', 'Y', 'R'][t % 5] ?? 'Y') : ch)
        const art = t < 13 ? ['.Y.', 'YWY', '.Y.'] : STAR
        c.stamp(out(target) - Math.floor(art[0]!.length / 2), 6 - Math.floor(art.length / 2), art, false, hue)
      }
    }
    return
  }

  const dy = Math.max(-headroom(creature), creature.isFloating && tick % 16 < 8 ? -1 : 0)
  const focus = creature.focus ?? { x: Math.floor(creature.wide / 2), y: 4 }
  if (move === 'teleport') {
    // Gone in a scatter of sparks, out into the open space, and back.
    const away = x + facing * 18
    const at = (x0: number) => {
      const own = new Canvas(c.width, TALL_H)
      drawFront(own, creature, x0, dy, 'idle', tick, false, true)
      return own.rows()
    }
    const frame =
      t < 4 ? dissolve(at(x), (t + 1) / 4, tick) : t < 9 ? dissolve(at(away), 1 - (t - 3) / 5, tick) : t < 13 ? dissolve(at(away), (t - 8) / 4, tick) : dissolve(at(x), 1 - (t - 12) / 5, tick)
    c.stamp(0, 0, frame)
    return
  }

  drawFront(c, creature, x, dy, 'idle', tick, false, true)
  const origin = { x: x + focus.x, y: focus.y + dy }
  if (move === 'mindbeam') {
    // The star flares, then a beam of shifting colour with rings rolling along it.
    if (t < 3) c.put(origin.x, origin.y, t % 2 ? 'W' : 'Y')
    else {
      const reach = (t - 2) * 6
      const gone = t < 16 ? 0 : (t - 15) * 8
      for (let d = Math.max(4, gone); d < reach; d++) {
        const px = origin.x + facing * d
        if (px < 0 || px >= c.width) break
        c.put(px, origin.y, PSY[Math.floor((d + t) / 2) % PSY.length]!)
        if ((d - t * 2) % 6 === 0) {
          c.put(px, origin.y - 1, 'v')
          c.put(px, origin.y + 1, 'v')
        }
      }
    }
    return
  }
  // Mind Wave: rings ripple out from its head, one after another, each a ( or ).
  for (const start of [2, 6, 10]) {
    const r = (t - start) * 3 + 4
    if (t < start || r > 40) continue
    const h = Math.min(5, Math.floor(r / 2))
    for (let k = -h; k <= h; k++) c.put(origin.x + facing * (r - Math.round(k * k * 0.4)), origin.y + k, (k + start) % 2 === 0 ? 'h' : 'v')
  }
}

/** Front-on and still with its eyes closed: what an evolution's silhouette is cut from. */
export function tallStill(line: TallLine, stage: number, width: number, x: number): string[] {
  const creature = LINES[line][stage]!
  const c = new Canvas(width, TALL_H)
  drawFront(c, creature, x, 0, 'idle', 0, true, false)
  return c.rows()
}

/** A tall line's strip: the form for `stage` at `x`, for the look, the walk and the nudge. */
export function tallPixels(line: TallLine, stage: number, width: number, x: number, look: Look, tick: number, stride: Stride, nudge: Nudge): string[] {
  const creature = LINES[line][stage]!
  const c = new Canvas(width, TALL_H)
  const side = x + creature.wide + 7 <= width ? 1 : -1
  const pose = poseFor(look, tick)
  const attack = pose.effect === 'none' ? tallAttackAt(line, stage, look, nudge, tick, stride.isWalking) : undefined
  if (attack) {
    drawAttack(c, creature, attack, x, side, tick)
    return c.rows()
  }

  if (stride.isWalking && creature.side) {
    drawSide(c, creature, x, stride.facing, tick % 4 < 2, tick)
    return c.rows()
  }

  const float = creature.isFloating && tick % 16 < 8 ? -1 : 0
  const dy = Math.max(-headroom(creature), pose.dy + float)
  const shut = pose.eyes === 'blink' || pose.eyes === 'shut' || pose.eyes === 'happy'
  const glow = pose.glow || look === 'delegating' || look === 'thinking'
  drawFront(c, creature, x, dy, look, tick, shut, glow)
  effectAt(c, pose.effect, x, dy + EFFECT_Y, tick, side, creature.wide, EFFECT_Y)
  if (pose.effect === 'none' && nudge !== 'none') {
    const at = side > 0 ? x + creature.wide + 1 : x - 2
    if (nudge === 'needs' && tick % 8 < 5) c.stamp(at, EFFECT_Y + 1, ['y', 'y', '.', 'y'])
    if (nudge === 'turn') {
      // Another session finished while this one works: an ember, or a psychic spark, beside it.
      const bob = EFFECT_Y + 2 + (Math.floor(tick / 6) % 2)
      c.stamp(at, bob, creature.flame ? (tick % 4 < 2 ? ['Y', 'R'] : ['F', 'R']) : [tick % 4 < 2 ? 'h' : 'v'])
    }
  }

  const rows = c.rows()
  // Teleporting: dissolving out of one place or into the next.
  return stride.fade ? dissolve(rows, stride.fade, tick) : rows
}

