/** What Claude is doing, as Sprout acts it out until something else happens. */
export type ActivityKind =
  | 'idle'
  | 'sleeping'
  | 'listening'
  | 'thinking'
  | 'talking'
  | 'reading'
  | 'writing'
  | 'running'
  | 'delegating'
  | 'asking'
  | 'awaiting'

/** A short reaction Sprout plays over the activity, then drops. */
export type ReactionKind = 'excited' | 'happy' | 'curious' | 'determined' | 'celebrate' | 'oops' | 'startled' | 'evolving'

/** The evolution line Sprout is drawn as, chosen with /avatar and kept between sessions. */
export type Avatar = 'toad' | 'lizard' | 'fox'

/** How far along its line, by how full the session's context window is: 0 fresh, 2 nearly full. */
export type Stage = 0 | 1 | 2

/** The Toad line's forms, as its sprite code names them. */
export type Form = 'sprout' | 'bud' | 'bloom'

export type Activity = { kind: ActivityKind; since: number }

/** `from` is what an `evolving` reaction changes from: an earlier stage, or the last avatar after /avatar. */
export type Reaction = { kind: ReactionKind; until: number; from?: { avatar: Avatar; stage: Stage } }

/** The model and effort the session runs on, as the label beside Sprout shows them. */
export type Engine = { model: string; effort: string }

declare module 'claude-code' {
  interface PluginState {
    sprout: { activity: Activity; reaction: Reaction | null; engine: Engine; stage: Stage; avatar: Avatar }
  }
}
